#!/usr/bin/env python3
"""
Test script to verify the ML model integration
"""

import sys
import os
sys.path.append(os.path.join(os.path.dirname(__file__), 'app'))

from predictor import compute_features, predict_mutation

def test_mutation_prediction():
    """Test the mutation prediction pipeline"""
    print("Testing mutation prediction pipeline...")
    
    # Test sequence (SARS-CoV-2 Spike protein)
    wt_seq = ""
    
    # Test mutations
    test_mutations = ["D614G", "N501Y", "E484K", "L452R", "T478K"]
    
    for mutation in test_mutations:
        try:
            print(f"\n--- Testing mutation: {mutation} ---")
            
            # Compute features
            features = compute_features(wt_seq, mutation)
            print(f"Features computed: {features}")
            
            # Make prediction
            prediction, confidence = predict_mutation(features)
            print(f"Prediction: {prediction} (confidence: {confidence:.3f})")
            
        except Exception as e:
            print(f"Error testing {mutation}: {e}")
    
    print("\n--- Integration test completed ---")

if __name__ == "__main__":
    test_mutation_prediction()
